em,5vw,4.5rem);align-items:start}.gld-tilt{display:grid;gap:1.2rem}.gld-tilt .gld-ph{aspect-ratio:4/3;border-radius:22px;box-shadow:0 30px 60px -30px rgba(0,0,0,.8)}.gld-tilt .gld-ph:first-child{transform:rotate(-2deg)}.gld-warn{padding:1.2rem 1.3rem;border-radius:20px;background:rgba(208,69,42,.16);outline:1px solid rgba(208,69,42,.4);outline-offset:-1px;color:#fff;font-size:.96rem;line-height:1.6}/* Trois pays */.gld-pays{padding:clamp(4rem,8vw,6.5rem) 0;background:var(--nuit)}.gld-pays-g{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(2rem,5vw,4.5rem);align-items:center}.gld-venn{position:relative;aspect-ratio:1.15;max-width:480px;margin:0 auto;width:100%}.gld-venn span{position:absolute;width:58%;aspect-ratio:1;border-radius:50%;display:grid;place-items:center;font-family:"Yeseva One",serif;font-size:1.25rem;color:#fff;mix-blend-mode:screen}.gld-venn span:nth-child(1){left:0;top:0;background:rgba(208,69,42,.55);place-items:start center;padding-top:22%}.gld-venn span:nth-child(2){right:0;top:0;background:rgba(54,160,106,.55);place-items:start center;padding-top:22%}.gld-venn span:nth-child(3){left:21%;bottom:0;background:rgba(242,163,58,.55);place-items:end center;padding-bottom:20%}.gld-ans{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1.6rem}.gld-ans div{padding:1.2rem 1.3rem;border-radius:20px;background:rgba(255,255,255,.06)}.gld-ans b{display:block;font-family:"Yeseva One",serif;font-weight:400;font-size:2.2rem;color:var(--lampe);line-height:1}.gld-ans span{font-size:.9rem;color:var(--soft)}.gld-lieux{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1rem}.gld-lieux span{padding:.5rem .95rem;border-radius:999px;background:rgba(255,255,255,.1);font-size:.88rem;color:#fff}/* Pratique */.gld-pr{position:relative;isolation:isolate;padding:clamp(4rem,8vw,6.5rem) 0;background:linear-gradient(180deg,var(--nuit),#1b1f52)}.gld-pr ul{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem;margin-top:1.4rem}.gld-pr li{padding:1.3rem 1.35rem;border-radius:22px;background:rgba(255,255,255,.06);outline:1px solid rgba(255,255,255,.12);outline-offset:-1px;font-size:.97rem;line-height:1.65;color:var(--soft);text-align:justify;hyphens:auto}.gld-pr li:last-child:nth-child(odd){grid-column:1/-1}.gld-pr li strong{display:block;margin-bottom:.4rem;font-size:.74rem;letter-spacing:.24em;text-transform:uppercase;color:var(--lampe);text-align:left}.gld-act{display:flex;flex-wrap:wrap;gap:1rem;justify-content:space-between;align-items:center;margin-top:2rem;padding:1.6rem 1.8rem;border-radius:24px;background:linear-gradient(90deg,rgba(242,163,58,.22),rgba(208,69,42,.22))}.gld-act p{color:#fff;font-family:"Yeseva One",serif;font-size:1.3rem}.gld-btn{padding:1rem 1.6rem;border-radius:999px;background:var(--lampe);color:var(--nuit)!important}@media (max-width:1000px){.gld-actes{grid-template-columns:repeat(2,1fr)}}@media (max-width:900px){.gld-scene-g,.gld-meres-g,.gld-nuit-g,.gld-pays-g{grid-template-columns:1fr}.gld-spot{max-width:420px;margin:0 auto}}@media (max-width:640px){.gld-actes,.gld-pr ul,.gld-ans{grid-template-columns:1fr}}</style><!-- Le Gèlèdè, une nuit sur la place : mise en page propre à cette page (préfixe gld). Textes et photos d'origine repris à l'identique et dans le même ordre, pour que les modifications de « Textes et images » continuent de s'appliquer. -->
<section class="gld-scene"><i class="gld-stars" aria-hidden="true"></i><div class="gld-in"><div class="gld-scene-g"><div class="gld-rv"><span class="gld-k">Une nuit de Gèlèdè</span><div class="gld-lead"><p>Dans le sud-est du Bénin, une société de masques yoruba-nago rend hommage à la puissance des mères. Chants satiriques, tambours et masques sculptés : une nuit de Gèlèdè règle les comptes du village.</p></div>
<div class="gld-years"><span><b>2001</b> chef-d'œuvre de l'UNESCO</span><span><b>2008</b> Liste représentative</span><span><b>3 pays</b> Bénin, Nigeria, Togo</span></div></div>
<div class="gld-spot gld-rv" data-big style="--dl:150ms"><div class="gld-ph" style="height:100%">@endverbatim<x-media.figure
    src="/assets/img/gelede-640x480.webp"
    alt="Masque Gèlèdè"
    loading="native"
    caption="Masque Gèlèdè"
    author="Brooklyn Museum / CC BY 3.0 — Wikimedia Commons"
/>@verbatim</div></div></div></div></section>
<div class="gld-band" aria-hidden="true"></div>

<section class="gld-meres"><div class="gld-in"><div class="gld-meres-g"><div class="gld-txt gld-rv"><span class="gld-k">Avant la nuit · Les mères</span><h2>Honorer Iyà Nlà, la mère primordiale</h2><div style="margin-top:1.4rem"><p>Le Gèlèdè est une cérémonie masquée pratiquée par les communautés yoruba-nago. Selon la fiche de l'UNESCO, elle rend hommage à Iyà Nlà, la mère primordiale, et au rôle des femmes dans l'organisation sociale yoruba. La puissance attribuée aux mères y est considérée comme redoutable autant que bénéfique : le rite vise à l'honorer et à l'apaiser, pas à la conjurer.</p><p>L'UNESCO décrit le Gèlèdè comme la seule société de masques connue qui soit également dirigée par des femmes. Les sources béninoises désignent à sa tête l'Iyalashè, une mère âgée qui ouvre les prières adressées aux divinités locales, aux ancêtres et aux Iyà. Le partage concret des rôles varie selon les localités et selon les auteurs.</p><p>La tradition béninoise fait de Kétou, dans le département du Plateau, le berceau du Gèlèdè. Une datation au XVIIIe siècle circule largement, mais elle repose sur la tradition orale et reste discutée.</p></div></div>
<div class="gld-orbit gld-rv" style="--dl:150ms"><div class="gld-med"><div><b>Iyà Nlà</b><span>la mère primordiale</span></div></div><div class="gld-med"><div><b>Iyalashè</b><span>la mère âgée qui ouvre les prières</span></div></div><div class="gld-med"><div><b>Kétou</b><span>berceau, selon la tradition</span></div></div><div class="gld-med"><div><b>Yoruba-nago</b><span>les communautés du Gèlèdè</span></div></div></div></div></div></section>

<section class="gld-nuit"><div class="gld-in"><div class="gld-rv" style="max-width:760px"><span class="gld-k">Sur la place · La sortie</span><h2>Ce qui se passe pendant une sortie</h2></div>
<div class="gld-actes"><div class="gld-acte gld-rv"><em>I</em><b>À l'écart</b><p>Les danseurs se préparent loin des regards.</p></div><div class="gld-acte gld-rv" style="--dl:100ms"><em>II</em><b>Les voix</b><p>Chanteurs et percussionnistes ouvrent la séance.</p></div><div class="gld-acte gld-rv" style="--dl:200ms"><em>III</em><b>Les masques</b><p>Orchestre et danseurs entrent, en pagnes superposés.</p></div><div class="gld-acte gld-rv" style="--dl:300ms"><em>IV</em><b>La satire</b><p>Les chants en yoruba passent l'année du village en revue.</p></div></div>
<div class="gld-nuit-g"><div class="gld-txt gld-rv"><p>La cérémonie a lieu la nuit, sur une place publique. Les danseurs se préparent à l'écart. Chanteurs et percussionnistes ouvrent la séance ; suivent l'orchestre et les danseurs masqués en costumes de pagnes superposés.</p><p>Les chants sont en langue yoruba. Ils transmettent l'histoire et les mythes des Yoruba-nago, mais ils commentent aussi la vie du village de l'année écoulée. Le ton est souvent satirique : on moque un notable trop gourmand, un mari violent, une rumeur mal éteinte. Les masques sculptés, portés au-dessus de la tête, portent sur leur plateau des scènes entières qui prolongent le propos.</p><p>D'où la fonction sociale : le Gèlèdè dit publiquement ce qui ne se dit pas en face. C'est un outil de régulation, pas une revue de music-hall. L'UNESCO signale d'ailleurs que le tourisme menace l'élément en le transformant en produit folklorique.</p></div><div class="gld-tilt gld-rv" style="--dl:150ms"><div class="gld-ph" data-big>@endverbatim<x-media.figure
    src="/assets/img/wikimedia/gelede-masked-dancer-ketou-benin.webp"
    alt="Un danseur masqué de Gèlèdè à Kétou"
    loading="native"
    caption="Un danseur de Gèlèdè à Kétou"
    author="Jonathanbwilson1 / CC BY-SA 4.0 — Wikimedia Commons"
/>@verbatim</div><p class="gld-warn">Photos et vidéos : uniquement avec l'accord préalable des responsables du culte, demandé par un intermédiaire local.</p></div></div></div></section>

<section class="gld-pays"><div class="gld-in"><div class="gld-pays-g"><div class="gld-rv"><div class="gld-tilt"><div class="gld-ph" data-big style="aspect-ratio:4/5">@endverbatim<x-media.figure
    src="/assets/img/wikimedia/les-collines-de-save.webp"
    alt="Les collines de Savè"
    loading="native"
    caption="Les collines de Savè"
    author="OBA / CC BY-SA 3.0 — Wikimedia Commons"
/>@verbatim</div></div><div class="gld-lieux" style="margin-top:1.2rem"><span>Bénin</span><span>Nigeria</span><span>Togo</span></div></div>
<div class="gld-txt gld-rv" style="--dl:150ms"><span class="gld-k">Au-delà des frontières · Le patrimoine</span><h2>Un bien partagé entre trois pays</h2><div style="margin-top:1.4rem"><p>Le Gèlèdè n'est pas exclusivement béninois. L'élément est inscrit au nom du Bénin, du Nigeria et du Togo, sur toute l'aire yoruba-nago. Deux dates sont souvent confondues : le Gèlèdè a été proclamé chef-d'œuvre du patrimoine oral et immatériel de l'humanité en 2001, puis inscrit sur la Liste représentative en 2008, lors du transfert des chefs-d'œuvre vers la nouvelle liste.</p><p>Côté béninois, on parle surtout de Kétou, Savè, Kilibo et des communes du Plateau. Un plan d'action UNESCO mené d'octobre 2003 à novembre 2008, financé par le fonds-en-dépôt japonais, a soutenu des ateliers de sculpture, de danse et de costume à Kétou et Kilibo ; l'État béninois a fait construire une Maison internationale du Gèlèdè.</p><p>Les sorties suivent le calendrier communautaire : après les récoltes, lors de funérailles, d'installations ou en cas de sécheresse. Il n'existe pas d'horaire publié pour visiteurs. On y assiste parce qu'on a été invité, pas parce qu'on a acheté un billet.</p></div>
<div class="gld-ans"><div><b>2001</b><span>proclamation</span></div><div><b>2008</b><span>Liste représentative</span></div></div><div class="gld-lieux"><span>Kétou</span><span>Savè</span><span>Kilibo</span><span>Communes du Plateau</span></div></div></div></div></section>

<section class="gld-pr"><i class="gld-stars" aria-hidden="true"></i><div class="gld-in"><div class="gld-rv"><span class="gld-k">Pour y assister</span><h2>En pratique</h2><ul><li><strong>Où</strong>Kétou, département du Plateau, et communes voisines ; le Gèlèdè se pratique aussi au Nigeria et au Togo</li><li><strong>Y aller</strong>138 km depuis Cotonou selon le portail du gouvernement béninois, via Porto-Novo et Pobè</li><li><strong>Compter</strong>une nuit sur place pour une sortie, les cérémonies se prolongeant tard</li><li><strong>Meilleure période</strong>saison sèche pour la route ; pour le Gèlèdè lui-même, la période après les récoltes</li><li><strong>Bon à savoir</strong>ne photographiez ni ne filmez sans autorisation préalable des responsables du culte. La demande passe par un intermédiaire local, jamais directement sur la place.</li></ul>
<div class="gld-act"><p>Kétou et le Plateau, avec un intermédiaire local.</p><a class="gld-btn" href="/sejourner/toutes-les-infos-pratiques/nous-contacter">Nous contacter →</a></div></div></div></section>
